from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[2] / "reports" / "MDP"
original = (ROOT / 'climate_policy_timeline_2016_2025.tex').read_text(encoding='utf-8')
refs = {}
for line in original.splitlines():
    m = re.fullmatch(r'\\source\{([^}]+)\}\{([^}]+)\}\{([^}]+)\}\{([^}]+)\}', line)
    if m:
        key, author, title, url = m.groups()
        refs[key] = (author, title, url)

