used = list(dict.fromkeys(['ghgp', 'omnibus'] + [k for r in rows for k in r[-1].split(',')]))
assert not set(used) - set(refs)

intro = ('This inventory consolidates the 2016-2025 timeline, additional 2030-target instruments, selected national carbon-pricing measures in EU member states, and a dedicated Dutch regulations and incentives section. '
         'National taxes introduced before 2016 are included where they operated during the review period; this is not an exhaustive inventory of every member state. '
         'Repeated milestones for the same instrument are combined. R = regulation or binding legislation '
         '(including legally established incentives); I = initiative, strategy or voluntary programme. '
         'Affected firms include both directly regulated entities and indirect beneficiaries or supply-chain partners, '
         'as indicated. Firm eligibility is summarized, not reproduced as an exhaustive legal test. '
         'Dates after 2025 describe schedules associated with the reviewed measures, not a full current-law update. '
         'The Scope 3 column contains analytical interpretations of potential decision channels, not claims that each '
         'instrument imposes a Scope 3 obligation or has already delivered reductions.')
notes = ('A supplier\'s operational emissions may enter its customer\'s Scope 3 purchased-goods inventory. '
         'The customer\'s own purchased electricity is generally Scope 2; outsourced transport can enter Scope 3. '
         'Carbon pricing, tax credits or offset purchases alone do not demonstrate a reduction in the buyer\'s inventory. '
         'CSRD/CSDDD scope descriptions follow the historical measures: the December 2025 Omnibus agreement was '
         'provisional, with substantive final adoption occurring after this review period.')

def esc(s):
    return ''.join({'&': r'\&', '%': r'\%', '$': r'\$', '#': r'\#', '_': r'\_', '{': r'\{', '}': r'\}'}.get(c, c) for c in s)

tex = r'''% Standalone landscape table with embedded bibliography. Compile twice with pdflatex.
\documentclass[10pt,a4paper,landscape]{article}
\usepackage[T1]{fontenc}
\usepackage[utf8]{inputenc}
\usepackage[margin=15mm]{geometry}
\usepackage{lmodern,microtype,array,tabularx,booktabs,xurl}
% Extend tabularx to allow page breaks and repeated table headers.
\usepackage{ltablex}
\keepXColumns
\usepackage[hidelinks]{hyperref}
\newcolumntype{Y}[1]{>{\hsize=#1\hsize\linewidth=\hsize\raggedright\arraybackslash}X}
\setlength{\parindent}{0pt}
\setlength{\parskip}{5pt}
\setlength{\tabcolsep}{4pt}
\renewcommand{\arraystretch}{1.18}
\newcommand{\source}[4]{\bibitem{#1} #2. \emph{#3}. \url{#4}.}
\title{Climate Policy Instruments and Scope 3 Decisions}
\author{TRACE3 --- Work Package 4}
\date{Policy review period 2016--2025}
\begin{document}
\maketitle
'''
tex += esc(intro) + '\n\n' + esc(notes) + r'\cite{ghgp,omnibus}' + '\n'
md = '# Climate policy instruments and Scope 3 decisions\n\n' + intro + '\n\n' + notes + '\n\n'
md += 'Accounting reference: [GHG Protocol](' + refs['ghgp'][2] + '). Historical scope note: [December 2025 agreement](' + refs['omnibus'][2] + ').\n\n'

for region in ['Global', 'European Union', 'EU member states', 'Netherlands', 'United States', 'Asia']:
    tex += '\n\\clearpage\n\\section*{' + esc(region) + '}\n\\small\n'
    tex += r'\begin{tabularx}{\textwidth}{Y{0.85}Y{1.00}Y{0.85}Y{1.05}Y{1.25}}' + '\n'
    header = r'\textbf{Instrument and type} & \textbf{Purpose and target} & \textbf{Affected firms} & \textbf{Implementation dates} & \textbf{Potential Scope 3 connection} \\'
    tex += '\\toprule\n' + header + '\n\\midrule\n\\endfirsthead\n\\toprule\n' + header + '\n\\midrule\n\\endhead\n'
    tex += r'\midrule \multicolumn{5}{r}{Continued on next page} \\ \endfoot \bottomrule \endlastfoot' + '\n'
    md += '**' + region + '**\n\n| Instrument and type | Purpose and target | Affected firms | Implementation dates | Potential Scope 3 connection |\n|---|---|---|---|---|\n'
    for row in (r for r in rows if r[0] == region):
        _, instrument, purpose, firms, dates, connection, keys = row
        cells = [esc(instrument) + r'\cite{' + keys + '}', esc(purpose), esc(firms), esc(dates), esc(connection)]
        tex += ' & '.join(cells) + r' \\' + '\n\\addlinespace[5pt]\n'
        citations = ' '.join('[Source ' + str(i+1) + '](' + refs[k][2] + ')' for i,k in enumerate(keys.split(',')))
        md += '| ' + ' | '.join([instrument + ' ' + citations, purpose, firms, dates, connection]) + ' |\n'
    tex += '\\end{tabularx}\n\\normalsize\n'
    md += '\n'

tex += '\\clearpage\n\\begin{thebibliography}{99}\n\\small\n'
tex += 'References reused from the timeline were accessed on 24 September 2026; supplementary references were checked on 25 September 2026.\n\n'
for key in used:
    author, title, url = refs[key]
    tex += '\\source{' + key + '}{' + esc(author) + '}{' + esc(title) + '}{' + url.replace('%', r'\%') + '}\n'
tex += '\\end{thebibliography}\n\\end{document}\n'
(ROOT / 'climate_policy_scope3_inventory.tex').write_text(tex, encoding='utf-8')
(ROOT / 'climate_policy_scope3_inventory.md').write_text(md, encoding='utf-8')
print(f'Created LaTeX and Markdown inventories: {len(rows)} instruments; {len(used)} bibliography entries.')
